<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const kind=ref('预案类型'),value=ref('');const add=()=>{actions.updateConfig(kind.value,value.value);value.value=''};</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">配</div><div><h2>基础配置</h2><p>维护常用业务分类与流程</p></div></div><div class="button-row"><button v-for="(_,k) in state.configs" :key="k" class="secondary-button" @click="kind=k">{{k}}</button></div><article class="panel"><h3>{{kind}}</h3><div class="button-row"><input v-model="value" placeholder="输入新增内容"><button class="primary-button active" @click="add">新增</button></div><div class="mini-list"><div v-for="v in state.configs[kind]" :key="v"><span>{{v}}</span><button class="secondary-button" @click="actions.toggleConfig(kind,v)">停用</button></div></div></article></section></template>
